void mergeRange(vector<int>& a, vector<int>& buf, int lo, int mid, int hi) {
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) buf[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];  // <= keeps it stable
    while (i < mid) buf[k++] = a[i++];
    while (j < hi)  buf[k++] = a[j++];
    copy(buf.begin() + lo, buf.begin() + hi, a.begin() + lo);
}
void msort(vector<int>& a, vector<int>& buf, int lo, int hi) {
    if (hi - lo < 2) return;                 // 0 or 1 element is already sorted
    int mid = lo + (hi - lo) / 2;
    msort(a, buf, lo, mid);
    msort(a, buf, mid, hi);
    if (a[mid - 1] <= a[mid]) return;        // already ordered: skip the merge
    mergeRange(a, buf, lo, mid, hi);
}
