int lomutoPartition(vector<int>& a, int lo, int hi) {
    int r = lo + rand() % (hi - lo + 1);
    swap(a[r], a[hi]);                   // randomised pivot parked at the end
    int pivot = a[hi], i = lo - 1;
    for (int j = lo; j < hi; ++j)
        if (a[j] <= pivot) swap(a[++i], a[j]);
    swap(a[i + 1], a[hi]);
    return i + 1;                        // pivot is now in its FINAL position
}
void quickSort(vector<int>& a, int lo, int hi) {
    if (lo >= hi) return;
    int p = lomutoPartition(a, lo, hi);
    quickSort(a, lo, p - 1);             // pivot itself is excluded from both sides
    quickSort(a, p + 1, hi);
}

long long mergeCount(vector<int>& a, vector<int>& buf, int lo, int hi) {
    if (hi - lo < 2) return 0;
    int mid = lo + (hi - lo) / 2;
    long long inv = mergeCount(a, buf, lo, mid) + mergeCount(a, buf, mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) buf[k++] = a[i++];
        else { inv += mid - i; buf[k++] = a[j++]; }   // a[i..mid) all exceed a[j]
    }
    while (i < mid) buf[k++] = a[i++];
    while (j < hi)  buf[k++] = a[j++];
    copy(buf.begin() + lo, buf.begin() + hi, a.begin() + lo);
    return inv;
}
long long countInversions(vector<int> a) {
    vector<int> buf(a.size());
    return mergeCount(a, buf, 0, (int)a.size());
}

