def count_inversions(a: list[int]) -> int:
    def sort_count(arr):
        if len(arr) < 2:
            return arr, 0
        mid = len(arr) // 2
        left, il = sort_count(arr[:mid])
        right, ir = sort_count(arr[mid:])
        merged, inv = [], il + ir
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i]); i += 1
            else:
                inv += len(left) - i       # left[i:] all exceed right[j]
                merged.append(right[j]); j += 1
        merged += left[i:]
        merged += right[j:]
        return merged, inv
    return sort_count(a)[1]

