vector<int> relativeSortArray(const vector<int>& arr1, const vector<int>& arr2) {
    vector<int> count(1001, 0);          // constraint: 0 <= values <= 1000
    for (int x : arr1) ++count[x];
    vector<int> out;
    out.reserve(arr1.size());
    for (int x : arr2) {                 // emit in arr2's order
        while (count[x]-- > 0) out.push_back(x);
        count[x] = 0;                    // the -- above leaves it at -1
    }
    for (int v = 0; v <= 1000; ++v)      // leftovers, ascending
        while (count[v]-- > 0) out.push_back(v);
    return out;
}

string frequencySort(const string& s) {
    unordered_map<char,int> freq;
    for (char c : s) ++freq[c];
    vector<string> buckets(s.size() + 1);        // frequency can never exceed n
    for (auto& [c, f] : freq) buckets[f].append(f, c);
    string out;
    out.reserve(s.size());
    for (int f = (int)s.size(); f >= 1; --f) out += buckets[f];
    return out;
}

