def frequency_sort(s: str) -> str:
    freq = {}
    for c in s:
        freq[c] = freq.get(c, 0) + 1
    buckets = [[] for _ in range(len(s) + 1)]    # frequency can never exceed n
    for c, f in freq.items():
        buckets[f].append(c * f)
    out = []
    for f in range(len(s), 0, -1):
        out.extend(buckets[f])
    return "".join(out)

