import functools


def largest_number(nums: list[int]) -> str:
    s = [str(x) for x in nums]
    s.sort(key=functools.cmp_to_key(
        lambda a, b: -1 if a + b > b + a else (1 if a + b < b + a else 0)))
    if s and s[0] == "0":
        return "0"                      # all zeros: avoid "000"
    return "".join(s)

