int heightChecker(const vector<int>& heights) {
    vector<int> count(101, 0);          // constraint: 1 <= height <= 100
    for (int h : heights) ++count[h];
    int mismatches = 0, idx = 0;
    for (int h = 1; h <= 100; ++h)
        while (count[h]-- > 0)          // rebuild the expected order in place
            if (heights[idx++] != h) ++mismatches;
    return mismatches;
}

