def height_checker(heights: list[int]) -> int:
    count = [0] * 101                   # constraint: 1 <= height <= 100
    for h in heights:
        count[h] += 1
    mismatches = idx = 0
    for h in range(1, 101):
        for _ in range(count[h]):       # rebuild the expected order in place
            if heights[idx] != h:
                mismatches += 1
            idx += 1
    return mismatches

