vector<int> pancakeSort(vector<int> a) {
    vector<int> flips;
    for (int size = (int)a.size(); size > 1; --size) {
        int maxIdx = (int)(max_element(a.begin(), a.begin() + size) - a.begin());
        if (maxIdx == size - 1) continue;          // already parked: no flips needed
        if (maxIdx > 0) {
            reverse(a.begin(), a.begin() + maxIdx + 1);   // max to the front
            flips.push_back(maxIdx + 1);
        }
        reverse(a.begin(), a.begin() + size);      // front to its final slot
        flips.push_back(size);
    }
    return flips;
}

