def pancake_sort(a: list[int]) -> list[int]:
    a = a[:]
    flips = []
    for size in range(len(a), 1, -1):
        max_idx = a.index(max(a[:size]))
        if max_idx == size - 1:
            continue                       # already parked: no flips needed
        if max_idx > 0:
            a[:max_idx + 1] = reversed(a[:max_idx + 1])   # max to the front
            flips.append(max_idx + 1)
        a[:size] = reversed(a[:size])      # front to its final slot
        flips.append(size)
    return flips
